// 定义一个函数，用于处理不同类型的文件
function handleFile(file) {
  if (file.type === 'jpg') {
    // 如果是图片文件，进行图片处理
    processImageFile(file);
  } else if (file.type === 'pdf') {
    // 如果是PDF文件，进行PDF处理
    processPdfFile(file);
  } else if (file.type === 'txt') {
    // 如果是文本文件，进行文本处理
    processTextFile(file);
  } else {
    // 如果是其他类型的文件，进行默认处理
    defaultHandleFile(file);
  }
}

